SELECT s.hadm_id, s.stay_id, percentile_cont(0.25) within GROUP (ORDER BY s.num_diagnoses) AS q1_diagnoses, percentile_cont(0.50) within GROUP (ORDER BY s.num_diagnoses) AS q2_diagnoses, percentile_cont(0.75) within GROUP (ORDER BY s.num_diagnoses) AS q3_diagnoses, percentile_cont(0.25) within GROUP (ORDER BY m.num_procedures) AS q1_procedures, percentile_cont(0.50) within GROUP (ORDER BY m.num_procedures) AS q2_procedures, percentile_cont(0.75) within GROUP (ORDER BY m.num_procedures) AS q3_procedures FROM (SELECT h.hadm_id, h.stay_id, COUNT(d.icd_code) AS num_diagnoses FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN diagnoses_icd d ON a.subject_id = d.subject_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 88 AND 98 AND d.icd_code IN ('426.0', '426.1', '426.9') GROUP BY h.hadm_id, h.stay_id) AS s JOIN (SELECT i.hadm_id, COUNT(i.icd_code) AS num_procedures FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN procedures_icd i ON a.subject_id = i.subject_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 88 AND 98 AND i.icd_code IN ('426.0', '426.1', '426.9') GROUP BY i.hadm_id) AS m ON s.hadm_id = m.hadm_id GROUP BY s.hadm_id, s.stay_id;